package rules; import java.util.ArrayList;import java.util.List; public final class RuleLexer{public List<RuleToken> lex(String text){List<RuleToken> out=new ArrayList<>();if(text==null)return out;StringBuilder sb=new StringBuilder();boolean quote=false;for(int i=0;i<text.length();i++){char c=text.charAt(i);if(c=='"'){sb.append(c);quote=!quote;}else if(Character.isWhitespace(c)&&!quote){flush(out,sb,i);}else if("();".indexOf(c)>=0&&!quote){flush(out,sb,i);out.add(new RuleToken(String.valueOf(c),i));}else sb.append(c);}flush(out,sb,text.length());return out;}private void flush(List<RuleToken> out,StringBuilder sb,int off){if(sb.length()>0){out.add(new RuleToken(sb.toString(),off-sb.length()));sb.setLength(0);}}}
